# Пример локального приложения с зависимостями fastapi и pydantic
from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()
class Order(BaseModel):
    distance_km: float = Field(gt=0, le=200)

@app.post('/predict')
def predict(order: Order):
    return {'eta_min': 8 + 3 * order.distance_km, 'version': 'baseline-1'}

