def config_id(config):
    import hashlib, json
    raw = json.dumps(config, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()

def valid_order(row):
    v = row.get('distance_km') if isinstance(row, dict) else None
    return isinstance(v, (int, float)) and not isinstance(v, bool) and 0 < v <= 200

def p95(latencies):
    import math
    return sorted(latencies)[math.ceil(0.95 * len(latencies)) - 1] if latencies else None

def largest_shift(old, new):
    zones = set(old) | set(new)
    return min(zones, key=lambda z: (-abs(new.get(z, 0) - old.get(z, 0)), z)) if zones else None

def ready_stages(dag, completed):
    done = set(completed)
    return sorted(n for n, deps in dag.items() if n not in done and set(deps) <= done)
